  parseJSON = A.withObject "AppTypeMultipliers" $ \o ->
    AppTypeMultipliers
      <$> (o .:? "APP_TYPE")

-- | ToJSON AppTypeMultipliers
instance A.ToJSON AppTypeMultipliers where
  toJSON AppTypeMultipliers {..} =
   _omitNulls
      [ "APP_TYPE" .= appTypeMultipliersAppType
      ]


-- | Construct a value of type 'AppTypeMultipliers' (by applying it's required fields, if any)
mkAppTypeMultipliers
  :: AppTypeMultipliers
mkAppTypeMultipliers =
  AppTypeMultipliers
  { appTypeMultipliersAppType = Nothing
  }

