      , "engagement_type" .= audienceRuleEngagementType
      , "engager_type" .= audienceRuleEngagerType
      , "event" .= audienceRuleEvent
      , "event_data" .= audienceRuleEventData
      , "event_source" .= audienceRuleEventSource
      , "ingestion_source" .= audienceRuleIngestionSource
      , "objective_type" .= audienceRuleObjectiveType
