data CatalogsFeedVideoCounts = CatalogsFeedVideoCounts
  { catalogsFeedVideoCountsIngestedVideos :: !(Maybe Int) -- ^ "ingested_videos" - The number of videos successfully ingested from the feed file.
  , catalogsFeedVideoCountsNotIngestedVideos :: !(Maybe Int) -- ^ "not_ingested_videos" - The number of videos that were not ingested from the feed file.
  , catalogsFeedVideoCountsTotalVideos :: !(Maybe Int) -- ^ "total_videos" - The number of videos in the feed file.
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON CatalogsFeedVideoCounts
instance A.FromJSON CatalogsFeedVideoCounts where
  parseJSON = A.withObject "CatalogsFeedVideoCounts" $ \o ->
    CatalogsFeedVideoCounts
      <$> (o .:? "ingested_videos")
      <*> (o .:? "not_ingested_videos")
      <*> (o .:? "total_videos")

-- | ToJSON CatalogsFeedVideoCounts
instance A.ToJSON CatalogsFeedVideoCounts where
  toJSON CatalogsFeedVideoCounts {..} =
   _omitNulls
      [ "ingested_videos" .= catalogsFeedVideoCountsIngestedVideos
      , "not_ingested_videos" .= catalogsFeedVideoCountsNotIngestedVideos
      , "total_videos" .= catalogsFeedVideoCountsTotalVideos
      ]


