-- ** CatalogsItems
-- | CatalogsItems
-- Response object of catalogs items
data CatalogsItems = CatalogsItems
  { catalogsItemsItems :: !(Maybe [ItemResponse]) -- ^ "items" - Array with catalogs items
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON CatalogsItems
instance A.FromJSON CatalogsItems where
  parseJSON = A.withObject "CatalogsItems" $ \o ->
    CatalogsItems
      <$> (o .:? "items")

-- | ToJSON CatalogsItems
instance A.ToJSON CatalogsItems where
  toJSON CatalogsItems {..} =
   _omitNulls
      [ "items" .= catalogsItemsItems
      ]


-- | Construct a value of type 'CatalogsItems' (by applying it's required fields, if any)
mkCatalogsItems
  :: CatalogsItems
mkCatalogsItems =
  CatalogsItems
  { catalogsItemsItems = Nothing
  }

-- ** CatalogsItemsBatch
-- | CatalogsItemsBatch
-- Object describing the catalogs items batch
data CatalogsItemsBatch = CatalogsItemsBatch
  { catalogsItemsBatchCatalogType :: !(CatalogsType) -- ^ /Required/ "catalog_type"
  , catalogsItemsBatchBatchId :: !(Maybe Text) -- ^ "batch_id" - Id of the catalogs items batch
  , catalogsItemsBatchCompletedTime :: !(Maybe DateTime) -- ^ /ReadOnly/ "completed_time" - Date and time (UTC) of the batch completion: YYYY-MM-DD&#39;T&#39;hh:mm:ss
  , catalogsItemsBatchCreatedTime :: !(DateTime) -- ^ /Required/ /ReadOnly/ "created_time" - Date and time (UTC) of the batch creation: YYYY-MM-DD&#39;T&#39;hh:mm:ss
  , catalogsItemsBatchItems :: !(Maybe [CreativeAssetsProcessingRecord]) -- ^ "items" - Array with the catalogs items processing records part of the catalogs items batch
  , catalogsItemsBatchStatus :: !(Maybe BatchOperationStatus) -- ^ "status"
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON CatalogsItemsBatch
instance A.FromJSON CatalogsItemsBatch where
  parseJSON = A.withObject "CatalogsItemsBatch" $ \o ->
    CatalogsItemsBatch
      <$> (o .:  "catalog_type")
      <*> (o .:? "batch_id")
      <*> (o .:? "completed_time")
      <*> (o .:  "created_time")
      <*> (o .:? "items")
      <*> (o .:? "status")

-- | ToJSON CatalogsItemsBatch
instance A.ToJSON CatalogsItemsBatch where
  toJSON CatalogsItemsBatch {..} =
   _omitNulls
      [ "catalog_type" .= catalogsItemsBatchCatalogType
      , "batch_id" .= catalogsItemsBatchBatchId
      , "completed_time" .= catalogsItemsBatchCompletedTime
      , "created_time" .= catalogsItemsBatchCreatedTime
      , "items" .= catalogsItemsBatchItems
      , "status" .= catalogsItemsBatchStatus
      ]


-- | Construct a value of type 'CatalogsItemsBatch' (by applying it's required fields, if any)
mkCatalogsItemsBatch
  :: CatalogsType -- ^ 'catalogsItemsBatchCatalogType' 
  -> DateTime -- ^ 'catalogsItemsBatchCreatedTime': Date and time (UTC) of the batch creation: YYYY-MM-DD'T'hh:mm:ss
  -> CatalogsItemsBatch
mkCatalogsItemsBatch catalogsItemsBatchCatalogType catalogsItemsBatchCreatedTime =
  CatalogsItemsBatch
  { catalogsItemsBatchCatalogType
  , catalogsItemsBatchBatchId = Nothing
  , catalogsItemsBatchCompletedTime = Nothing
  , catalogsItemsBatchCreatedTime
  , catalogsItemsBatchItems = Nothing
  , catalogsItemsBatchStatus = Nothing
  }

