  , conversionProductReportRequestStartDate :: !(Text) -- ^ /Required/ "start_date" - Metric report start date (UTC). Format: YYYY-MM-DD.&lt;br&gt; Start date must be after 2024-03-16. 7 day minimum time window for report is required.
  , conversionProductReportRequestViewWindowDays :: !(Maybe ConversionAttributionWindowDays) -- ^ "view_window_days" - Number of days to use as the conversion attribution window for a view action. Applies to Pinterest Tag conversion metrics. Prior conversion tags use their defined attribution windows. If not specified, defaults to &#x60;30&#x60; day.
  } deriving (P.Show, P.Eq, P.Typeable)

