-- ** TrendingKeyword
-- | TrendingKeyword
-- TrendingKeyword
-- 
data TrendingKeyword = TrendingKeyword
  { trendingKeywordDemographics :: !(Maybe TrendingKeywordDemographics) -- ^ "demographics"
  , trendingKeywordHasPrediction :: !(Maybe Bool) -- ^ "has_prediction" - Indicates whether the keyword has a prediction available for the next 90 days.&lt;br /&gt; This field is only applicable when &#x60;include_prediction&#x60; query parameter is set to &#x60;true&#x60;. &lt;br /&gt; By default, the value is &#x60;false&#x60; and no prediction data is included in the response.
  , trendingKeywordKeyword :: !(Maybe Text) -- ^ "keyword" - The keyword that is trending.
  , trendingKeywordPctGrowthMom :: !(Maybe Int) -- ^ "pct_growth_mom" - The month-over-month percent change in search volume for this keyword.&lt;br /&gt; For example, a value of \&quot;400\&quot; would represent a 400% increase in searches in the last 30 days compared to the month prior.&lt;br /&gt; **Note**: growth rates are rounded, with a maximum of +/- 10000% change.  A value of 10001 indicates that this keyword experienced &gt; 10000% month-over-month growth.
  , trendingKeywordPctGrowthWow :: !(Maybe Int) -- ^ "pct_growth_wow" - The week-over-week percent change in search volume for this keyword.&lt;br /&gt; For example, a value of \&quot;50\&quot; would represent a 50% increase in searches in the last seven days compared to the week prior.&lt;br /&gt; **Note**: growth rates are rounded, with a maximum of +/- 10000% change.  A value of 10001 indicates that this keyword experienced &gt; 10000% week-over-week growth.
  , trendingKeywordPctGrowthYoy :: !(Maybe Int) -- ^ "pct_growth_yoy" - The year-over-year percent change in search volume for this keyword.&lt;br /&gt; For example, a value of \&quot;-5\&quot; would represent a 5% decrease in searches in the last 365 days compared to the month prior.&lt;br /&gt; **Note**: growth rates are rounded, with a maximum of +/- 10000% change.  A value of 10001 indicates that this keyword experienced &gt; 10000% year-over-year growth.
  , trendingKeywordPredictedTimeSeries :: !(Maybe PredictedTimeSeries) -- ^ "predicted_time_series"
  , trendingKeywordTimeSeries :: !(Maybe TimeSeries) -- ^ "time_series"
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON TrendingKeyword
instance A.FromJSON TrendingKeyword where
  parseJSON = A.withObject "TrendingKeyword" $ \o ->
    TrendingKeyword
      <$> (o .:? "demographics")
      <*> (o .:? "has_prediction")
      <*> (o .:? "keyword")
      <*> (o .:? "pct_growth_mom")
      <*> (o .:? "pct_growth_wow")
      <*> (o .:? "pct_growth_yoy")
      <*> (o .:? "predicted_time_series")
      <*> (o .:? "time_series")

-- | ToJSON TrendingKeyword
instance A.ToJSON TrendingKeyword where
  toJSON TrendingKeyword {..} =
   _omitNulls
      [ "demographics" .= trendingKeywordDemographics
      , "has_prediction" .= trendingKeywordHasPrediction
      , "keyword" .= trendingKeywordKeyword
      , "pct_growth_mom" .= trendingKeywordPctGrowthMom
      , "pct_growth_wow" .= trendingKeywordPctGrowthWow
      , "pct_growth_yoy" .= trendingKeywordPctGrowthYoy
      , "predicted_time_series" .= trendingKeywordPredictedTimeSeries
      , "time_series" .= trendingKeywordTimeSeries
      ]


-- | Construct a value of type 'TrendingKeyword' (by applying it's required fields, if any)
mkTrendingKeyword
  :: TrendingKeyword
mkTrendingKeyword =
  TrendingKeyword
  { trendingKeywordDemographics = Nothing
  , trendingKeywordHasPrediction = Nothing
  , trendingKeywordKeyword = Nothing
  , trendingKeywordPctGrowthMom = Nothing
  , trendingKeywordPctGrowthWow = Nothing
  , trendingKeywordPctGrowthYoy = Nothing
  , trendingKeywordPredictedTimeSeries = Nothing
  , trendingKeywordTimeSeries = Nothing
  }

-- ** TrendingKeywordDemographics
-- | TrendingKeywordDemographics
-- A mapping of demographic dimensions (e.g. \"gender\", \"age\") to their category distributions. <br /> For each dimension: <br />   - Key: The category (e.g., \"female\", \"18-24\"). <br />   - Value: The proportion of search volume (e.g., 0.12 for 12%). <br />     Values less than 0.05 are set to 0.04 for privacy. <br />     The sum for all categories in a dimension will approximately equal 1. <br />     Only applicable when `include_demographics` query parameter is set to `true`.
data TrendingKeywordDemographics = TrendingKeywordDemographics
  { trendingKeywordDemographicsAgeDistribution :: !(Maybe TrendingKeywordDemographicsAgeDistribution) -- ^ "age_distribution"
  , trendingKeywordDemographicsGenderDistribution :: !(Maybe TrendingKeywordDemographicsGenderDistribution) -- ^ "gender_distribution"
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON TrendingKeywordDemographics
instance A.FromJSON TrendingKeywordDemographics where
  parseJSON = A.withObject "TrendingKeywordDemographics" $ \o ->
    TrendingKeywordDemographics
      <$> (o .:? "age_distribution")
      <*> (o .:? "gender_distribution")

-- | ToJSON TrendingKeywordDemographics
instance A.ToJSON TrendingKeywordDemographics where
  toJSON TrendingKeywordDemographics {..} =
   _omitNulls
      [ "age_distribution" .= trendingKeywordDemographicsAgeDistribution
      , "gender_distribution" .= trendingKeywordDemographicsGenderDistribution
      ]


-- | Construct a value of type 'TrendingKeywordDemographics' (by applying it's required fields, if any)
mkTrendingKeywordDemographics
  :: TrendingKeywordDemographics
mkTrendingKeywordDemographics =
  TrendingKeywordDemographics
  { trendingKeywordDemographicsAgeDistribution = Nothing
  , trendingKeywordDemographicsGenderDistribution = Nothing
  }

