data TrendingTopic = TrendingTopic
  { trendingTopicDescription :: !(Text) -- ^ /Required/ "description" - Description of the trending topic
  , trendingTopicPercentGrowthMom :: !(Int) -- ^ /Required/ "percent_growth_mom" - Month-over-month growth percentage
  , trendingTopicPins :: !([TrendingPin]) -- ^ /Required/ "pins" - Array of pin images related to this trend (up to 6)
  , trendingTopicRelatedInterests :: !([Text]) -- ^ /Required/ "related_interests" - List of related interest categories
  , trendingTopicRelatedSearches :: !([Text]) -- ^ /Required/ "related_searches" - List of related search terms
  , trendingTopicTimeSeries :: !((Map.Map String Double)) -- ^ /Required/ "time_series" - Time series data showing trend values over time, with dates as keys and values as numeric
  , trendingTopicTitle :: !(Text) -- ^ /Required/ "title" - Title of the trending topic
  } deriving (P.Show, P.Eq, P.Typeable)

-- | FromJSON TrendingTopic
instance A.FromJSON TrendingTopic where
  parseJSON = A.withObject "TrendingTopic" $ \o ->
    TrendingTopic
      <$> (o .:  "description")
      <*> (o .:  "percent_growth_mom")
      <*> (o .:  "pins")
      <*> (o .:  "related_interests")
      <*> (o .:  "related_searches")
      <*> (o .:  "time_series")
      <*> (o .:  "title")

-- | ToJSON TrendingTopic
instance A.ToJSON TrendingTopic where
  toJSON TrendingTopic {..} =
   _omitNulls
      [ "description" .= trendingTopicDescription
      , "percent_growth_mom" .= trendingTopicPercentGrowthMom
      , "pins" .= trendingTopicPins
      , "related_interests" .= trendingTopicRelatedInterests
      , "related_searches" .= trendingTopicRelatedSearches
      , "time_series" .= trendingTopicTimeSeries
      , "title" .= trendingTopicTitle
      ]


-- | Construct a value of type 'TrendingTopic' (by applying it's required fields, if any)
mkTrendingTopic
  :: Text -- ^ 'trendingTopicDescription': Description of the trending topic
  -> Int -- ^ 'trendingTopicPercentGrowthMom': Month-over-month growth percentage
  -> [TrendingPin] -- ^ 'trendingTopicPins': Array of pin images related to this trend (up to 6)
  -> [Text] -- ^ 'trendingTopicRelatedInterests': List of related interest categories
  -> [Text] -- ^ 'trendingTopicRelatedSearches': List of related search terms
  -> (Map.Map String Double) -- ^ 'trendingTopicTimeSeries': Time series data showing trend values over time, with dates as keys and values as numeric
  -> Text -- ^ 'trendingTopicTitle': Title of the trending topic
  -> TrendingTopic
mkTrendingTopic trendingTopicDescription trendingTopicPercentGrowthMom trendingTopicPins trendingTopicRelatedInterests trendingTopicRelatedSearches trendingTopicTimeSeries trendingTopicTitle =
  TrendingTopic
  { trendingTopicDescription
  , trendingTopicPercentGrowthMom
  , trendingTopicPins
  , trendingTopicRelatedInterests
  , trendingTopicRelatedSearches
  , trendingTopicTimeSeries
  , trendingTopicTitle
  }

