instance A.ToJSON Country where toJSON = A.toJSON . fromCountry
instance A.FromJSON Country where parseJSON o = P.either P.fail (pure . P.id) . toCountry =<< A.parseJSON o
instance WH.ToHttpApiData Country where toQueryParam = WH.toQueryParam . fromCountry
instance WH.FromHttpApiData Country where parseQueryParam o = WH.parseQueryParam o >>= P.left T.pack . toCountry
instance MimeRender MimeMultipartFormData Country where mimeRender _ = mimeRenderDefaultMultipartFormData

