instance A.ToJSON NonNullableProductAvailabilityType where toJSON = A.toJSON . fromNonNullableProductAvailabilityType
instance A.FromJSON NonNullableProductAvailabilityType where parseJSON o = P.either P.fail (pure . P.id) . toNonNullableProductAvailabilityType =<< A.parseJSON o
