instance WH.FromHttpApiData NonNullableProductAvailabilityType where parseQueryParam o = WH.parseQueryParam o >>= P.left T.pack . toNonNullableProductAvailabilityType
instance MimeRender MimeMultipartFormData NonNullableProductAvailabilityType where mimeRender _ = mimeRenderDefaultMultipartFormData

