  = ObjectiveType'AWARENESS -- ^ @"AWARENESS"@
  | ObjectiveType'CONSIDERATION -- ^ @"CONSIDERATION"@
  | ObjectiveType'WEB_CONVERSION -- ^ @"WEB_CONVERSION"@
  | ObjectiveType'CATALOG_SALES -- ^ @"CATALOG_SALES"@
  | ObjectiveType'VIDEO_COMPLETION -- ^ @"VIDEO_COMPLETION"@
