toProductCategoryRegion :: Text -> P.Either String ProductCategoryRegion
toProductCategoryRegion = \case
  "US" -> P.Right ProductCategoryRegion'US
  "GB+IE" -> P.Right ProductCategoryRegion'GBIE
  "CA" -> P.Right ProductCategoryRegion'CA
