  PromotionType'EXTRA_PERCENT_OFF -> "EXTRA_PERCENT_OFF"
  PromotionType'GIFT_WITH_PURCHASE -> "GIFT_WITH_PURCHASE"
  PromotionType'GIFT_WITH_PURCHASE_MINIMUM -> "GIFT_WITH_PURCHASE_MINIMUM"
  PromotionType'FIXED -> "FIXED"
  PromotionType'PERCENT_OFF_CLEARANCE -> "PERCENT_OFF_CLEARANCE"
  PromotionType'X_OFF_Y -> "X_OFF_Y"
  PromotionType'GIFT_WITH_FIRST_PURCHASE -> "GIFT_WITH_FIRST_PURCHASE"
  PromotionType'BUY_X_GET_ONE_FREE -> "BUY_X_GET_ONE_FREE"
  PromotionType'CASH_BACK -> "CASH_BACK"
  PromotionType'POINTS_ON_ALL_PURCHASES -> "POINTS_ON_ALL_PURCHASES"
  PromotionType'BONUS -> "BONUS"
  PromotionType'POINTS_WITH_PURCHASE -> "POINTS_WITH_PURCHASE"
  PromotionType'CUSTOM -> "CUSTOM"

-- | parse 'PromotionType' enum
toPromotionType :: Text -> P.Either String PromotionType
toPromotionType = \case
  "VARIABLE" -> P.Right PromotionType'VARIABLE
  "SITEWIDE" -> P.Right PromotionType'SITEWIDE
  "CHECKOUT" -> P.Right PromotionType'CHECKOUT
  "SAVE_X_ON_Y" -> P.Right PromotionType'SAVE_X_ON_Y
  "BUY_X_GET_Y" -> P.Right PromotionType'BUY_X_GET_Y
  "SPEND_X_SAVE_Y" -> P.Right PromotionType'SPEND_X_SAVE_Y
  "FREE_SHIPPING" -> P.Right PromotionType'FREE_SHIPPING
  "FREE_SHIPPING_MINIMUM" -> P.Right PromotionType'FREE_SHIPPING_MINIMUM
  "FREE_SHIPPING_WITH_DISCOUNT" -> P.Right PromotionType'FREE_SHIPPING_WITH_DISCOUNT
  "SITEWIDE_IN_STORES" -> P.Right PromotionType'SITEWIDE_IN_STORES
  "EXTRA_PERCENT_OFF" -> P.Right PromotionType'EXTRA_PERCENT_OFF
  "GIFT_WITH_PURCHASE" -> P.Right PromotionType'GIFT_WITH_PURCHASE
  "GIFT_WITH_PURCHASE_MINIMUM" -> P.Right PromotionType'GIFT_WITH_PURCHASE_MINIMUM
  "FIXED" -> P.Right PromotionType'FIXED
  "PERCENT_OFF_CLEARANCE" -> P.Right PromotionType'PERCENT_OFF_CLEARANCE
  "X_OFF_Y" -> P.Right PromotionType'X_OFF_Y
  "GIFT_WITH_FIRST_PURCHASE" -> P.Right PromotionType'GIFT_WITH_FIRST_PURCHASE
  "BUY_X_GET_ONE_FREE" -> P.Right PromotionType'BUY_X_GET_ONE_FREE
  "CASH_BACK" -> P.Right PromotionType'CASH_BACK
  "POINTS_ON_ALL_PURCHASES" -> P.Right PromotionType'POINTS_ON_ALL_PURCHASES
  "BONUS" -> P.Right PromotionType'BONUS
  "POINTS_WITH_PURCHASE" -> P.Right PromotionType'POINTS_WITH_PURCHASE
  "CUSTOM" -> P.Right PromotionType'CUSTOM
  s -> P.Left $ "toPromotionType: enum parse failure: " P.++ P.show s


